---
import { cn } from "@/utils/cn";
import type { HTMLAttributes } from "astro/types";

export interface Props extends HTMLAttributes<"div"> {
  type?: "single" | "multiple";
  variant?: "default" | "outline";
  size?: "sm" | "default" | "lg";
  orientation?: "horizontal" | "vertical";
  disabled?: boolean;
  defaultValue?: string | string[];
}

const {
  type = "single",
  variant = "default",
  size = "default",
  orientation = "horizontal",
  disabled = false,
  defaultValue,
  class: className,
  ...props
} = Astro.props;

const classes = cn(
  "inline-flex",
  orientation === "vertical" ? "flex-col items-stretch" : "flex-row items-center",
  className
);
---

<div
  role="group"
  data-toggle-group
  data-type={type}
  data-variant={variant}
  data-size={size}
  data-orientation={orientation}
  data-disabled={disabled ? "true" : undefined}
  data-default-value={Array.isArray(defaultValue) ? defaultValue.join(",") : defaultValue}
  class={classes}
  {...props}
>
  <slot />
</div>

<style>
  /* Horizontal orientation - connected buttons */
  [role="group"][data-toggle-group][data-orientation="horizontal"]
    > :global(*:not(:first-child):not(:last-child)) {
    border-radius: 0;
  }
  [role="group"][data-toggle-group][data-orientation="horizontal"]
    > :global(*:first-child:not(:last-child)) {
    border-top-right-radius: 0;
    border-bottom-right-radius: 0;
  }
  [role="group"][data-toggle-group][data-orientation="horizontal"]
    > :global(*:last-child:not(:first-child)) {
    border-top-left-radius: 0;
    border-bottom-left-radius: 0;
  }
  [role="group"][data-toggle-group][data-orientation="horizontal"]
    > :global(*:not(:first-child)) {
    margin-left: -1px;
  }

  /* Vertical orientation - connected buttons */
  [role="group"][data-toggle-group][data-orientation="vertical"]
    > :global(*:not(:first-child):not(:last-child)) {
    border-radius: 0;
  }
  [role="group"][data-toggle-group][data-orientation="vertical"]
    > :global(*:first-child:not(:last-child)) {
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
  }
  [role="group"][data-toggle-group][data-orientation="vertical"]
    > :global(*:last-child:not(:first-child)) {
    border-top-left-radius: 0;
    border-top-right-radius: 0;
  }
  [role="group"][data-toggle-group][data-orientation="vertical"]
    > :global(*:not(:first-child)) {
    margin-top: -1px;
  }
</style>

<script>
  function initToggleGroups() {
    document.querySelectorAll('[data-toggle-group]').forEach(group => {
      if (group.hasAttribute('data-initialized')) return;
      group.setAttribute('data-initialized', 'true');

      const type = group.getAttribute('data-type') || 'single';
      const variant = group.getAttribute('data-variant') || 'default';
      const size = group.getAttribute('data-size') || 'default';
      const isDisabled = group.getAttribute('data-disabled') === 'true';
      const defaultValue = group.getAttribute('data-default-value');

      const items = group.querySelectorAll('[data-toggle-group-item]');

      // Apply variant and size to all items
      items.forEach(item => {
        item.setAttribute('data-variant', variant);
        item.setAttribute('data-size', size);

        if (isDisabled) {
          item.setAttribute('disabled', 'true');
          item.setAttribute('data-disabled', 'true');
        }
      });

      // Set default values
      if (defaultValue) {
        const values = defaultValue.split(',');
        items.forEach(item => {
          const itemValue = item.getAttribute('data-value');
          if (itemValue && values.includes(itemValue)) {
            item.setAttribute('aria-pressed', 'true');
            item.setAttribute('data-state', 'on');
          }
        });
      }

      // Handle item clicks
      items.forEach(item => {
        item.addEventListener('click', (e) => {
          e.stopPropagation();

          if (item.hasAttribute('disabled')) return;

          const isPressed = item.getAttribute('aria-pressed') === 'true';

          if (type === 'single') {
            // Deselect all items
            items.forEach(i => {
              i.setAttribute('aria-pressed', 'false');
              i.setAttribute('data-state', 'off');
            });

            // Select clicked item (unless it was already selected)
            if (!isPressed) {
              item.setAttribute('aria-pressed', 'true');
              item.setAttribute('data-state', 'on');
            }
          } else {
            // Multiple selection - toggle the clicked item
            const newState = !isPressed;
            item.setAttribute('aria-pressed', String(newState));
            item.setAttribute('data-state', newState ? 'on' : 'off');
          }

          // Dispatch custom event with current values
          const selectedValues: string[] = [];
          items.forEach(i => {
            if (i.getAttribute('aria-pressed') === 'true') {
              const val = i.getAttribute('data-value');
              if (val) selectedValues.push(val);
            }
          });

          group.dispatchEvent(new CustomEvent('toggle-group-change', {
            bubbles: true,
            detail: { 
              value: type === 'single' ? (selectedValues[0] || null) : selectedValues 
            }
          }));
        });
      });
    });
  }

  initToggleGroups();
  document.addEventListener('astro:page-load', initToggleGroups);
</script>

---
import { cn } from "@/utils/cn";
import type { HTMLAttributes } from "astro/types";

export interface Props extends HTMLAttributes<"button"> {
  value: string;
  variant?: "default" | "outline";
  size?: "sm" | "default" | "lg";
  disabled?: boolean;
}

const {
  value,
  variant = "default",
  size = "default",
  disabled = false,
  class: className,
  ...props
} = Astro.props;

const baseClasses = cn(
  "inline-flex items-center justify-center gap-2 text-sm font-medium",
  "ring-offset-background transition-colors",
  "hover:bg-muted hover:text-muted-foreground",
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
  "disabled:pointer-events-none disabled:opacity-50",
  "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  // Pressed state - takes precedence over hover
  "data-[state=on]:bg-accent data-[state=on]:text-accent-foreground"
);

const variantClasses = {
  default: "border border-input bg-transparent",
  outline: "border border-input bg-transparent",
};

const sizeClasses = {
  sm: "h-8 px-2 min-w-8",
  default: "h-9 px-2.5 min-w-9",
  lg: "h-10 px-3 min-w-10",
};

// Rounded corners and border overlap are handled by ToggleGroup parent styles
const classes = cn(
  baseClasses,
  variantClasses[variant],
  sizeClasses[size],
  "rounded-md",
  className
);
---

<button
  type="button"
  data-toggle-group-item
  data-value={value}
  data-variant={variant}
  data-size={size}
  data-state="off"
  aria-pressed="false"
  disabled={disabled}
  class={classes}
  {...props}
>
  <slot />
</button>
